class Solution {
public:
    int findKOr(vector<int>& nums, int k) {
        int ans = 0;
        for (int b = 0; b < 31; b++) {
            int cnt = 0;
            for (int x : nums) {
                if ((x >> b) & 1) cnt++;
            }
            if (cnt >= k) ans |= (1 << b);
        }
        return ans;
    }
};

class Solution {
    public int findKOr(int[] nums, int k) {
        int ans = 0;
        for (int b = 0; b < 31; b++) {
            int cnt = 0;
            for (int x : nums) {
                if (((x >> b) & 1) == 1) cnt++;
            }
            if (cnt >= k) ans |= (1 << b);
        }
        return ans;
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @return {number}
 */
var findKOr = function(nums, k) {
    let ans = 0;
    for (let b = 0; b < 31; b++) {
        let cnt = 0;
        for (const x of nums) {
            if ((x >> b) & 1) cnt++;
        }
        if (cnt >= k) ans |= (1 << b);
    }
    return ans;
};
